-- The two checklists published on 2026-11-10: When Jealousy Gets Into a
-- Relationship (Jealousy) and Getting Children to Bed Without a Fight
-- (Bedtime).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-10`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-jealousy-gets-into-a-relationship', 'When Jealousy Gets Into a Relationship', 'For jealousy that has got a grip and started running the relationship. It gets the feeling said once without a case attached, stops the checking, separates the story from the facts, and agrees what you each consider out of bounds.', 'Jealousy', '["Say the feeling plainly once, without building a case — naming it lands better than presenting evidence.", "Stop checking their phone and their history — checking feeds the very thing it means to settle.", "Ask yourself what you are afraid of losing — jealousy is usually fear wearing a different coat.", "Write the story you are telling yourself, then the facts — put the two side by side and read both.", "Ask one direct question rather than six indirect ones — hinting gets an answer you cannot trust.", "Agree what you both consider out of bounds — much of this is two people assuming different rules.", "Put something of your own back in the week — jealousy grows in a life that has shrunk to one person.", "Notice whether this predates them — a pattern you brought with you is not theirs to reassure away.", "Take it to a counselor if it will not settle — some of this is older than the relationship."]'::jsonb, 'as needed', array['Relationships', 'Thinking Traps', 'Self-Esteem']::text[], 1, '2026-11-10T16:00:00+00:00'::timestamptz),
  ('getting-children-to-bed-without-a-fight', 'Getting Children to Bed Without a Fight', 'For the hour before a child''s bedtime, when it turns into a negotiation every night. It starts the wind-down earlier, keeps the same order, takes screens out of the last hour, and moves the hard conversation to the morning.', 'Bedtime', '["Start the wind-down half an hour before you think — bedtime runs late mostly because it starts late.", "Keep the same order every night — the sequence does the work, not the argument.", "Give the warning in minutes they can see — a timer argues far less well than you do.", "Take screens out of the last hour — the fight you have at nine usually began at eight.", "Offer two choices that are both bedtime — pajamas first or teeth first is still bed.", "Answer the fourth request for water once, then stop — every extra answer buys another request.", "Keep your voice flat when theirs goes up — one calm person in the room is the whole technique.", "Put the hard conversation in the morning — nothing gets resolved at bedtime by anybody.", "Expect two weeks before it settles — a new routine gets worse before it starts working."]'::jsonb, 'daily', array['Parenting', 'Habits', 'Boundaries']::text[], 1, '2026-11-10T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
